// === Tab: main ===
let metaballShader;
const N_balls = 200,metaballs = [];
let gra;
let kpFrame = 0;


function preload() {
	metaballShader = getShader(this._renderer);
}

function setup() {
	pixelDensity(1);
	createCanvas(windowWidth, windowHeight, WEBGL);
	shader(metaballShader);
	for (let i = 0; i < N_balls; i ++) metaballs.push(new Metaball());
	gra = createGraphics(30,30);
}

function draw() {
	if(frameCount == kpFrame + 20 && kpFrame != 0)for(let i = 0; i < metaballs.length; i++)metaballs[i].changeState(true);

	var data = [];
	for (const ball of metaballs) {
		ball.update();
		data.push(ball.pos.x, ball.pos.y, ball.radius);
	}

	metaballShader.setUniform("metaballs", data);
	rect(0, 0,width, height);
}


//////////


function keyPressed(){
	updateGra(key,gra);
	let targetPos = getBlPxPos(gra);
	setTargetPos(targetPos);
	kpFrame = frameCount;
	for(let i = 0; i < metaballs.length; i++)metaballs[i].changeState(false);
}


function setTargetPos(pos)
{
	for(let i =0; i < metaballs.length; i++)
	{
		if(i < pos.length)metaballs[i].setTarget(pos[i].x,pos[i].y);
		else
		{
			let d;
			if(random() > 0.5)d = random() > 0.5 ? createVector(-metaballs[i].radius*5,random(height)) : createVector(width + metaballs[i].radius*5,random(height));
			else d = random() > 0.5 ? createVector(random(width),-metaballs[i].radius*5) : createVector(random(width),height + metaballs[i].radius*5);
			metaballs[i].setTarget(d.x,d.y);
		}
	}
}


function getBlPxPos(g)
{
	let ratio = max(width, height)/g.height;
	let pos = [];
	for(let x =0 ; x < g.width; x++)
	{
		for(let y =0; y < g.height; y++)
		{
			let col = g.get(x,y);
			if(brightness(col) == 0)pos.push(createVector((x-g.width/2)*ratio + width/2,((g.height-y)-g.height/2)*ratio + height/2));
		}
	}
	return pos;
}


function updateGra(str,g,s = g.height)
{
	g.background(255);
	g.fill(0);
	g.textSize(s);
	g.textAlign(CENTER,CENTER);
	g.text(str,g.width/2,g.height/2);
}

// OpenProcessing has a bug where it always creates a scrollbar on Chromium.
function mouseWheel() { // This stops the canvas from scrolling by a few pixels.
	return false;
}

// === Tab: metaball ===
class Metaball {
	constructor() {
		this.vel = this.initVel();
		this.pos = new p5.Vector(width / 2, height / 2);
		this.targetPos = createVector(width / 2, height / 2);
		this.gotoTarget = false;
		this.frameOff = Math.floor(random(50));
		this.diagonalSize = dist(0,0,width,height);
	}

	update()
	{
		this.radius =  this.diagonalSize*(0.009 + sin(frameCount/10 + this.frameOff)*0.003);
		if(this.gotoTarget)this.vel = p5.Vector.sub(this.targetPos,this.pos).mult(0.1);
		else
		{
			if (this.pos.x < this.radius && this.vel.x <0 || this.pos.x > width  - this.radius && this.vel.x >0) this.vel.x *= -1;
			if (this.pos.y < this.radius && this.vel.y <0 || this.pos.y > height - this.radius && this.vel.y >0) this.vel.y *= -1;
		}
		this.pos.add(this.vel);
	}

	setTarget(x,y)
	{
		this.targetPos = createVector(x, y);
	}

	changeState(isGo)
	{
		if(this.gotoTarget && isGo == false)this.vel = this.initVel();
		this.gotoTarget = isGo;
	}

	initVel()
	{
		const size = Math.pow(Math.random(), 2);
		return p5.Vector.random2D().mult(8 * (1 - size) + 2);
	}
}

// === Tab: shader ===
function getShader(_renderer) {
	const vert = `
		attribute vec3 aPosition;
		attribute vec2 aTexCoord;

		varying vec2 vTexCoord;

		void main() {
			vTexCoord = aTexCoord;

			vec4 positionVec4 = vec4(aPosition, 1.0);
			positionVec4.xy = positionVec4.xy * 2.0 - 1.0;

			gl_Position = positionVec4;
		}
	`;

	const frag = `
		precision highp float;

		varying vec2 vTexCoord;

		uniform vec3 metaballs[${N_balls}];

		const float WIDTH = ${windowWidth}.0;
		var float HEIGHT = ${windowHeight}.0;

		vec3 hsv2rgb(vec3 c) {
				vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
				vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
				return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
		}

		void main() {
			float x = vTexCoord.x * WIDTH;
			float y = vTexCoord.y * HEIGHT;
			float v = 0.0;

			for (int i = 0; i < ${N_balls}; i++) {
				vec3 ball = metaballs[i];
				float dx = ball.x - x;
				float dy = ball.y - y;
				float r = ball.z;
				v += r * r / (dx * dx + dy * dy);
			}

			if (0.9 < v && v < 1.1) {
				float a = (v - 0.9) * 4.;
				gl_FragColor = vec4(hsv2rgb(vec3(a, 1., 1.)), 1.0);
			} else gl_FragColor = vec4(0.0, 0.0, 0.0, 1.0);
		}
	`;

	return createShader(vert, frag);
}

